function validate([root, target, k]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs a root.';
  const values = root.filter(v => v !== null);
  if (values.length > 500) return 'The tree has at most 500 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 0 || v > 500)) return 'Node values are whole numbers from 0 to 500.';
  if (new Set(values).size !== values.length) return 'Node values must be unique.';
  // Every non-null entry must hang under an existing node in level order.
  let slots = 1;
  for (let i = 0; i < root.length; i++) {
    if (i >= slots) return 'Every node must have a parent earlier in the level-order array.';
    if (root[i] !== null) slots += 2;
  }
  if (!values.includes(target)) return 'target must be the value of a node in the tree.';
  if (!Number.isInteger(k) || k < 0 || k > 1000) return 'k is a whole number from 0 to 1000.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [values, target, k] = input;
  const root = kit.toTree(values);
  const result = solve(root, kit.findNode(root, target), k);
  if (!Array.isArray(result)) throw new Error('Return an array of node values.');
  return result;
}

