function distanceK(root, target, k) {
  // Record the path from the root to every node, then measure each pair through their shared prefix.
  const paths = [];
  const walk = (node, path) => {
    if (!node) return;
    const here = [...path, node];
    paths.push(here);
    walk(node.left, here);
    walk(node.right, here);
  };
  walk(root, []);
  const toTarget = paths.find(path => path[path.length - 1] === target);
  const answer = [];
  for (const path of paths) {
    let shared = 0;
    while (shared < path.length && shared < toTarget.length && path[shared] === toTarget[shared]) shared++;
    if (path.length + toTarget.length - 2 * shared === k) answer.push(path[path.length - 1].val);
  }
  return answer;
}

