function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 450 + pick(51) : 1 + pick(10);
  const deep = rand() < 0.3;
  // Draw distinct values from 0..500 (or a small range for tiny trees).
  const span = size === 'large' || rand() < 0.4 ? 501 : 21;
  const pool = Array.from({ length: span }, (_, i) => i);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const nodes = [{ val: pool[0], left: null, right: null }];
  while (nodes.length < n) {
    // Deep trees grow from the newest nodes; bushy trees attach a child anywhere.
    const parent = deep ? nodes[Math.max(0, nodes.length - 1 - pick(2))] : nodes[pick(nodes.length)];
    const side = rand() < 0.5 ? 'left' : 'right';
    if (parent[side]) continue;
    parent[side] = { val: pool[nodes.length], left: null, right: null };
    nodes.push(parent[side]);
  }
  const root = [];
  const queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    root.push(queue[q] ? queue[q].val : null);
    if (queue[q]) queue.push(queue[q].left, queue[q].right);
  }
  while (root[root.length - 1] === null) root.pop();
  const target = nodes[pick(n)].val;
  const k = rand() < 0.1 ? pick(1001) : size === 'large' ? pick(15) : pick(6);
  return [root, target, k];
}
